effect.shader:
float hash1(float n) {
    return fract(sin(n * 12.9898 + seed * 7.1) * 43758.5453);
}

float hash2(vec2 p) {
    return fract(sin(dot(p, vec2(12.9898, 78.233)) + seed * 7.1) * 43758.5453);
}

/** O tempo quantizado dá o "degrau" do glitch: cada tick, uma nova composição de saltos. */
float tickDoGlitch() {
    return floor(acTime * max(speed, 0.01));
}

void main() {
    // Progress 0 devolve a camada como está, igual ao AE.
    float p = clamp(progress * 0.01, 0.0, 1.0);
    if (p <= 0.0) {
        fragColor = texture(inputImg, acScreenNorm);
        return;
    }

    float tick = tickDoGlitch();
    vec2 uv = acScreenNorm;

    // -------------------------------------------------- 1. fatias horizontais
    // Quantas fatias: proporcional ao Horizontal Shift (um glitch com shift zero é só a aberração cromática).
    float rows = mix(12.0, 80.0, horizontalShift * 0.01);
    float row = floor(uv.y * rows);
    float semenduraDaLinha = hash1(row * 1.7 + tick * 17.3);
    float densidade = 0.25 + 0.5 * (horizontalShift * 0.01);
    float ativaLinha = step(1.0 - densidade, semenduraDaLinha);
    float saltoLinha = (hash1(semenduraDaLinha * 7.13) - 0.5) * (horizontalShift * 0.01) * 0.2 * ativaLinha * p;
    uv.x += saltoLinha;

    // -------------------------------------------------- 2. blocos quadrados
    float ladoBloco = mix(0.0, 0.08, blocky * 0.01);
    if (ladoBloco > 0.001) {
        vec2 bloco = floor(uv / ladoBloco);
        float ativaBloco = step(0.75 - 0.25 * (blocky * 0.01), hash2(bloco + tick));
        vec2 saltoBloco = (vec2(hash2(bloco + 1.3), hash2(bloco + 2.7)) - 0.5) * ladoBloco * 2.0 * ativaBloco * p;
        uv += saltoBloco;
    }

    // -------------------------------------------------- 3. pixelate
    float px = mix(0.0, 60.0, pixelate * 0.01) * p;
    if (px > 0.5) {
        vec2 grade = max(vec2(1.0), acTamanhoDaTela / px);
        uv = (floor(uv * grade) + 0.5) / grade;
    }

    uv = clamp(uv, 0.0, 1.0);

    // -------------------------------------------------- 4. separação de canais
    float split = (colorShift * 0.01) * 0.012 * p;
    vec4 r = texture(inputImg, clamp(uv + vec2(split, 0.0), 0.0, 1.0));
    vec4 g = texture(inputImg, uv);
    vec4 b = texture(inputImg, clamp(uv - vec2(split, 0.0), 0.0, 1.0));
    vec4 cor = vec4(r.r, g.g, b.b, g.a);

    // -------------------------------------------------- 5. scan lines (listras horizontais escuras)
    if (scanLines > 0.0) {
        float faixas = max(acTamanhoDaTela.y * 0.5, 60.0);
        float onda = 0.5 + 0.5 * cos(uv.y * faixas * 6.28318530718);
        float forca = (scanLines * 0.01) * 0.7 * p;
        cor.rgb *= mix(1.0, onda, forca);
    }

    // -------------------------------------------------- 6. ruído aditivo
    if (noiseAmount > 0.0) {
        float ruido = hash2(gl_FragCoord.xy + tick * 101.0) - 0.5;
        cor.rgb = clamp(cor.rgb + ruido * (noiseAmount * 0.01) * 0.5 * p, 0.0, 1.0);
    }

    fragColor = cor;
}
